    int after_reset_next = next(vec);
    TEST_ASSERT_EQUAL_INT(10, after_reset_next);

    helper_cleanup_vector(vec);
}

int main(void) {
    UNITY_BEGIN();
    RUN_TEST(unit_test_vector_reset_iterator_valid_vector);
    return UNITY_END();
}

